USE CakesDB; GO  CREATE OR ALTER PROCEDURE CalcOrderCost     @OrderId INT AS BEGIN     DECLARE @Cost DECIMAL(10,2);      SELECT @Cost = SUM(i.price_per_unit * r.quantity)     FROM Recipe r     JOIN Cakes c ON r.cake_id = c.id     JOIN Ingredients i ON r.ingredient_id = i.id     WHERE c.order_id = @OrderId;      IF @Cost IS NULL         SET @Cost = 0;      SET @Cost = @Cost * 1.3;      UPDATE Orders     SET total_cost = @Cost     WHERE id = @OrderId; END; GO   CREATE OR ALTER PROCEDURE CalcAllOrders AS BEGIN      UPDATE o     SET o.total_cost = sub.cost * 1.3      FROM Orders o     JOIN (         SELECT             c.order_id,             SUM(i.price_per_unit * r.quantity) AS cost         FROM Recipe r         JOIN Cakes c ON r.cake_id = c.id         JOIN Ingredients i ON r.ingredient_id = i.id         GROUP BY c.order_id     ) sub ON o.id = sub.order_id;  END; GO  EXEC CalcOrderCost 1; EXEC CalcAllOrders; 